<?php
require __DIR__.'/_bootstrap.php';$admin=current_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'');
 if($action==='password'){ $current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$q=$pdo->prepare('SELECT password_hash FROM admin_users WHERE admin_id=? AND is_active=1');$q->execute([$admin['admin_id']]);$hash=$q->fetchColumn();if(!$hash||!password_verify($current,$hash))flash('Current password is incorrect.');elseif(!admin_password_valid($new))flash('New password must be at least 12 characters.');elseif($new!==$confirm)flash('New password confirmation does not match.');else{$q=$pdo->prepare('UPDATE admin_users SET password_hash=? WHERE admin_id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$admin['admin_id']]);session_regenerate_id(true);flash('Admin password changed.');}go('admin/credentials.php'); }
 if($action==='add'){ $name=post_string('full_name',120);$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!admin_password_valid($password))flash('Enter a name, valid email, and a password of at least 12 characters.');else{try{$q=$pdo->prepare('INSERT INTO admin_users(full_name,email,password_hash) VALUES(?,?,?)');$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);flash('Admin account created. Share its credentials securely.');}catch(PDOException $exception){flash('Could not create this admin account; the email may already exist.');}}go('admin/credentials.php');}
 if($action==='deactivate'){ $id=(int)($_POST['admin_id']??0);if($id===(int)$admin['admin_id'])flash('You cannot deactivate your own signed-in account.');else{$active=(int)$pdo->query('SELECT COUNT(*) FROM admin_users WHERE is_active=1')->fetchColumn();if($active<=1)flash('Keep at least one active administrator.');else{$q=$pdo->prepare('UPDATE admin_users SET is_active=0 WHERE admin_id=?');$q->execute([$id]);flash('Admin account deactivated.');}}go('admin/credentials.php'); }
}
$admins=$pdo->query('SELECT admin_id,full_name,email,is_active,created_at FROM admin_users ORDER BY full_name')->fetchAll();$pageTitle='Admin credentials';require __DIR__.'/../includes/header.php';?>
<section class="content"><span class="eyebrow">SECURITY</span><h1>Admin credentials</h1><h2>Change your password</h2><form class="fields" method="post"><?php csrf_input();?><input type="hidden" name="action" value="password"><label>Current password<input type="password" name="current_password" required autocomplete="current-password"></label><label>New password (12+ characters)<input type="password" name="new_password" minlength="12" maxlength="200" required autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" minlength="12" maxlength="200" required autocomplete="new-password"></label><button class="button">Change password</button></form><h2>Add an administrator</h2><form class="fields" method="post"><?php csrf_input();?><input type="hidden" name="action" value="add"><label>Full name<input name="full_name" maxlength="120" required></label><label>Email<input type="email" name="email" maxlength="190" required></label><label>Temporary password (12+ characters)<input type="password" name="password" minlength="12" maxlength="200" required autocomplete="new-password"></label><button class="button">Create admin account</button></form><h2>Existing admins</h2><div class="list"><?php foreach($admins as $a):?><article><div><h3><?=e($a['full_name'])?></h3><p><?=e($a['email'])?> · <?=$a['is_active']?'Active':'Inactive'?> · Added <?=e($a['created_at'])?></p></div><?php if($a['is_active']&&(int)$a['admin_id']!==(int)$admin['admin_id']):?><form method="post"><?php csrf_input();?><input type="hidden" name="action" value="deactivate"><input type="hidden" name="admin_id" value="<?=e($a['admin_id'])?>"><button class="button pale">Deactivate</button></form><?php endif?></article><?php endforeach?></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
